  | AomiWalletKitProviderProps
  | {
      auth: {
        provider: "para";
        apiKey?: string;
        environment?: "PROD" | "BETA";
        methods?: readonly AuthMethodId[];
        appName?: string;
        appDescription?: string;
      };
      children: ReactNode;
    }
  | {
      auth: {
        provider: "privy";
        appId?: string;
        methods?: readonly AuthMethodId[];
        appName?: string;
      };
      children: ReactNode;
    };

"use client";

import type { ReactNode } from "react";
import type {
  AuthConfig,
  AomiWalletKitProviderInput,
  AomiWalletKitProviderProps,
  ExecutionConfig,
  ProvidersConfig,
} from "../config/types";
import type { SvmNetworkOption } from "../types";
import type { Chain } from "viem";

/**
 * A wallet provider plugin. Knows how to render itself from the normalized
 * capability config, and optionally how to recognize its ergonomic sugar form.
 * Registering one lets `AomiWalletKitProvider` resolve a provider by id instead
 * of branching on hardcoded provider names — adding a provider is a
 * `registerWalletProvider(...)` call, not a new `if` in the router.
 *
 */
export type WalletProviderPlugin = {
  id: string;
  authMode?: "additive" | "full";
  /** @deprecated plugins should use `wrap` + `renderComposer`. */
  render?: (props: AomiWalletKitProviderProps) => ReactNode;
  wrap?: (props: {
    auth?: AuthConfig;
    children: ReactNode;
    providers?: ProvidersConfig;
  }) => ReactNode;
  isAvailable?: (props: {
    auth?: AuthConfig;
    providers?: ProvidersConfig;
  }) => boolean;
  renderComposer?: (props: {
    auth?: AuthConfig;
    children: ReactNode;
    execution?: ExecutionConfig;
    providers?: ProvidersConfig;
    solanaRuntimeConfig?: {
      cluster: SvmNetworkOption["cluster"];
      rpcHttpUrl: string;
      rpcWsUrl?: string;
      preferDirectSend: boolean;
    };
    supportedChains: readonly Chain[];
    supportedSolanaNetworks: readonly SvmNetworkOption[];
    selectedSolanaNetwork?: SvmNetworkOption;
    setSelectedSolanaNetworkId: (networkId: string) => void;
  }) => ReactNode;
  detectSugar?: (
    input: AomiWalletKitProviderInput,
  ) => AomiWalletKitProviderProps | null;
};

const registry = new Map<string, WalletProviderPlugin>();

export function registerWalletProvider(plugin: WalletProviderPlugin): void {
  registry.set(plugin.id, plugin);
}

export function getWalletProvider(
  id: string,
): WalletProviderPlugin | undefined {
  return registry.get(id);
}

export function requireWalletProvider(id: string): WalletProviderPlugin {
  const plugin = registry.get(id);
  if (!plugin) {
    throw new Error(
      `[aomi-wallet-kit] Unknown wallet provider "${id}". Import @aomi-labs/widget-lib or the provider module before mounting AomiWalletKitProvider.`,
    );
  }
  return plugin;
}

/**
 * Run each registered plugin's sugar detector in registration order; the first
 * match wins. Replaces the previous isParaSugar/isPrivySugar chain without the
 * router naming a provider.
 */
export function detectProviderSugar(
  input: AomiWalletKitProviderInput,
): AomiWalletKitProviderProps | null {
  for (const plugin of registry.values()) {
    const normalized = plugin.detectSugar?.(input);
    if (normalized) return normalized;
  }
  return null;
}

"use client";

import type { Chain, Hex } from "viem";
import {
  createAAProviderState,
  type AAMode,
  type AAProvider,
} from "@aomi-labs/client";
import { toClientAAOwner, type AomiAAOwnerInput } from "../aa/owner";
import {
  getPreferredRpcUrl,
  type WalletKitAAProviderPreference,
  type RequestedAAMode,
  type WalletExecutionCallList,
  type WalletProviderState,
} from "../wallet-execution";
import type { EvmWalletRuntime } from "../runtime/evm/wallet-runtime";

const ALCHEMY_API_KEY = process.env.NEXT_PUBLIC_ALCHEMY_API_KEY?.trim() ?? "";
const ALCHEMY_GAS_POLICY_ID =
  process.env.NEXT_PUBLIC_ALCHEMY_GAS_POLICY_ID?.trim();
const PIMLICO_API_KEY = process.env.NEXT_PUBLIC_PIMLICO_API_KEY?.trim() ?? "";
const AA_PROVIDER_OVERRIDE =
  process.env.NEXT_PUBLIC_AA_PROVIDER?.trim().toLowerCase();

function resolveAAProvider(
  preference: WalletKitAAProviderPreference = "auto",
): AAProvider | null {
  if (preference === "alchemy" || preference === "pimlico") {
    return preference;
  }

  if (
    AA_PROVIDER_OVERRIDE === "alchemy" ||
    AA_PROVIDER_OVERRIDE === "pimlico"
  ) {
    return AA_PROVIDER_OVERRIDE;
  }

  if (PIMLICO_API_KEY) return "pimlico";
  if (ALCHEMY_API_KEY) return "alchemy";
  return null;
}

export async function resolveExternalWalletAAProviderState({
  callList,
  chainsById,
  requestedMode,
  shouldUseExternalSigner,
  walletClient,
  address,
  sponsored,
  provider: providerPreference = "auto",
}: {
  callList: WalletExecutionCallList;
  chainsById: Record<number, Chain>;
  requestedMode: Exclude<RequestedAAMode, "none">;
  shouldUseExternalSigner: boolean;
  walletClient: EvmWalletRuntime["walletClient"];
  address: string | undefined;
  sponsored?: boolean;
  provider?: WalletKitAAProviderPreference;
}): Promise<{
  providerState: WalletProviderState;
  resolvedMode: RequestedAAMode;
  fallbackReason?: string;
}> {
  let resolvedMode: RequestedAAMode = requestedMode;
  let fallbackReason: string | undefined;
  if (requestedMode === "7702") {
    resolvedMode = "4337";
    fallbackReason = "requested_7702_connected_wallet_fallback_4337";
  }

  const provider = resolveAAProvider(providerPreference);
  if (!provider) {
    return {
      providerState: { resolved: null, pending: false, error: null },
      resolvedMode,
      fallbackReason:
        fallbackReason ?? "aa_provider_not_configured_fallback_eoa",
    };
  }

  if (!shouldUseExternalSigner || !walletClient || !address) {
    return {
      providerState: { resolved: null, pending: false, error: null },
      resolvedMode,
      fallbackReason:
        fallbackReason ?? "external_wallet_unavailable_fallback_eoa",
    };
  }

  const chainId = callList[0]?.chainId;
  const chain = chainId ? chainsById[chainId] : undefined;
  if (!chainId || !chain) {
    return {
      providerState: { resolved: null, pending: false, error: null },
      resolvedMode,
      fallbackReason: fallbackReason ?? "aa_chain_not_supported_fallback_eoa",
    };
  }

  const apiKey =
    provider === "alchemy"
      ? ALCHEMY_API_KEY || undefined
      : PIMLICO_API_KEY || undefined;
  if (!apiKey) {
    return {
      providerState: { resolved: null, pending: false, error: null },
      resolvedMode,
      fallbackReason:
        fallbackReason ?? `aa_${provider}_api_key_missing_fallback_eoa`,
    };
  }

  const ownerInput: AomiAAOwnerInput = {
    kind: "external-wallet",
    walletClient,
    address: address as Hex,
  };

  try {
    const state = await createAAProviderState({
      provider,
      owner: toClientAAOwner(ownerInput),
      chain,
      rpcUrl: getPreferredRpcUrl(chain),
      callList,
      mode: resolvedMode as AAMode,
      apiKey,
      gasPolicyId: provider === "alchemy" ? ALCHEMY_GAS_POLICY_ID : undefined,
      sponsored,
    });

    if (!state.account || state.error) {
      console.warn(
        "[aomi-wallet-kit] External-wallet AA unavailable; falling back to EOA",
        {
          provider,
          mode: resolvedMode,
          error: state.error?.message ?? "account_unavailable",
        },
      );
      return {
        providerState: { resolved: null, pending: false, error: null },
        resolvedMode,
        fallbackReason:
          fallbackReason ??
          `aa_${provider}_external_wallet_unavailable_fallback_eoa`,
      };
    }

    return { providerState: state, resolvedMode, fallbackReason };
  } catch (error) {
    console.warn(
      "[aomi-wallet-kit] External-wallet AA init failed; falling back to EOA",
      {
        provider,
        mode: resolvedMode,
        error: error instanceof Error ? error.message : String(error),
      },
    );
    return {
      providerState: { resolved: null, pending: false, error: null },
      resolvedMode,
      fallbackReason:
        fallbackReason ??
        `aa_${provider}_external_wallet_initialization_failed_fallback_eoa`,
    };
  }
}

export function resolveAASponsorship(
  providerPreference: WalletKitAAProviderPreference = "auto",
): {
  sponsored: boolean;
  sponsorProvider: "alchemy" | "pimlico" | "self";
  sponsorAccount?: string;
} {
  const aaProvider = resolveAAProvider(providerPreference);
  if (aaProvider === "alchemy") {
    return {
      sponsored: Boolean(ALCHEMY_GAS_POLICY_ID),
      sponsorProvider: "alchemy",
      sponsorAccount: ALCHEMY_GAS_POLICY_ID || undefined,
    };
  }
  if (aaProvider === "pimlico") {
    return {
      sponsored: Boolean(PIMLICO_API_KEY),
      sponsorProvider: "pimlico",
      sponsorAccount: undefined,
    };
  }
  return {
    sponsored: false,
    sponsorProvider: "self",
    sponsorAccount: undefined,
  };
}

export async function resolveAAProviderState({
  ownerStrategy,
  walletClient,
  address,
  ...params
}: Parameters<typeof resolveExternalWalletAAProviderState>[0] & {
  ownerStrategy:
    | { kind: "external-wallet" }
    | { kind: "provider-session"; provider: string; session: unknown };
}) {
  if (ownerStrategy.kind === "external-wallet") {
    return resolveExternalWalletAAProviderState({
      ...params,
      walletClient,
      address,
    });
  }

  const shouldUseExternalSigner = params.shouldUseExternalSigner;
  return resolveProviderSessionAAProviderState({
    ...params,
    providerSession: ownerStrategy,
    walletClient,
    address,
    shouldUseExternalSigner,
  });
}

async function resolveProviderSessionAAProviderState({
  callList,
  chainsById,
  requestedMode,
  shouldUseExternalSigner,
  providerSession,
  walletClient,
  address,
  sponsored,
  provider: providerPreference = "auto",
}: Parameters<typeof resolveExternalWalletAAProviderState>[0] & {
  providerSession: { provider: string; session: unknown };
}) {
  let resolvedMode: RequestedAAMode = requestedMode;
  let fallbackReason: string | undefined;
  if (requestedMode === "7702" && shouldUseExternalSigner) {
    resolvedMode = "4337";
    fallbackReason = "requested_7702_connected_wallet_fallback_4337";
  }

  const provider = resolveAAProvider(providerPreference);
  if (!provider) {
    return {
      providerState: { resolved: null, pending: false, error: null },
      resolvedMode,
      fallbackReason:
        fallbackReason ?? "aa_provider_not_configured_fallback_eoa",
    };
  }

  const canUseExternalWalletOwner = Boolean(
    shouldUseExternalSigner && walletClient && address,
  );
  if (!providerSession.session && !canUseExternalWalletOwner) {
    return {
      providerState: { resolved: null, pending: false, error: null },
      resolvedMode,
      fallbackReason: fallbackReason ?? "provider_session_unavailable_fallback_eoa",
    };
  }

  const chainId = callList[0]?.chainId;
  const chain = chainId ? chainsById[chainId] : undefined;
  if (!chainId || !chain) {
    return {
      providerState: { resolved: null, pending: false, error: null },
      resolvedMode,
      fallbackReason: fallbackReason ?? "aa_chain_not_supported_fallback_eoa",
    };
  }

  const apiKey =
    provider === "alchemy"
      ? ALCHEMY_API_KEY || undefined
      : PIMLICO_API_KEY || undefined;
  if (!apiKey) {
    return {
      providerState: { resolved: null, pending: false, error: null },
      resolvedMode,
      fallbackReason:
        fallbackReason ?? `aa_${provider}_api_key_missing_fallback_eoa`,
    };
  }

  const ownerInput: AomiAAOwnerInput = canUseExternalWalletOwner
    ? {
        kind: "external-wallet",
        walletClient,
        address: address as Hex,
      }
    : {
        kind: "provider-session",
        provider: providerSession.provider,
        session: providerSession.session,
        address: address as Hex | undefined,
      };

  try {
    const state = await createAAProviderState({
      provider,
      owner: toClientAAOwner(ownerInput),
      chain,
      rpcUrl: getPreferredRpcUrl(chain),
      callList,
      mode: resolvedMode as AAMode,
      apiKey,
      gasPolicyId: provider === "alchemy" ? ALCHEMY_GAS_POLICY_ID : undefined,
      sponsored,
    });

    if (!state.account || state.error) {
      console.warn("[aomi-wallet-kit] AA unavailable; falling back to EOA", {
        provider,
        mode: resolvedMode,
        error: state.error?.message ?? "account_unavailable",
      });
      return {
        providerState: { resolved: null, pending: false, error: null },
        resolvedMode,
        fallbackReason:
          fallbackReason ?? `aa_${provider}_account_unavailable_fallback_eoa`,
      };
    }

    return { providerState: state, resolvedMode, fallbackReason };
  } catch (error) {
    console.warn("[aomi-wallet-kit] AA init failed; falling back to EOA", {
      provider,
      mode: resolvedMode,
      error: error instanceof Error ? error.message : String(error),
    });
    return {
      providerState: { resolved: null, pending: false, error: null },
      resolvedMode,
      fallbackReason:
        fallbackReason ?? `aa_${provider}_initialization_failed_fallback_eoa`,
    };
  }
}

"use client";

import {
  toViemSignMessageArgs,
  toViemSignTypedDataArgs,
} from "@aomi-labs/react";
import type { EvmExecutionRuntime } from "../composer/types";
import type { EvmWalletRuntime } from "../runtime/evm/wallet-runtime";
import {
  executeWalletKitTransaction,
  getPreferredRpcUrl,
} from "./wallet-execution";

/**
 * Map a shared `EvmWalletRuntime` into the composer's `EvmExecutionRuntime`
 * shape. Every provider lane (Para, Privy, wallets-only) passes the same dozen
 * wagmi passthrough fields; the only differences are provider-specific
 * `overrides` (AA owner resolution, smart-wallet send/sign), so they spread on
 * top. Keeps the signing surface in one place instead of three copies.
 */
export function buildEvmExecutionRuntime(
  evm: EvmWalletRuntime,
  overrides?: Partial<EvmExecutionRuntime>,
): EvmExecutionRuntime {
  const runtime: EvmExecutionRuntime = {
    activeConnector: evm.activeConnector,
    capabilities: evm.capabilities,
    chainsById: evm.chainsById,
    currentChainId: evm.activeEvmConnection?.chainId,
    getWalletClientFor: evm.getWalletClientFor,
    sendCallsSyncAsync: evm.sendCallsSyncAsync,
    sendTransactionAsync: evm.sendTransactionAsync,
    shouldUseExternalSigner: evm.shouldUseExternalSigner,
    signMessageAsync: evm.signMessageAsync,
    signTypedDataAsync: evm.signTypedDataAsync,
    switchChainAsync: evm.switchChainAsync,
    walletClient: evm.walletClient,
    ...overrides,
  };
  const shouldUseExternalSignerForAA =
    runtime.aaOwner === "provider-session"
      ? false
      : runtime.aaOwner === "external-wallet"
        ? true
        : runtime.shouldUseExternalSigner;

  return {
    ...runtime,
    sendTransaction:
      runtime.sendTransaction ??
      (runtime.sendTransactionAsync
        ? async (payload) =>
            executeWalletKitTransaction({
              payload,
              state: {
                currentChainId: runtime.currentChainId,
                capabilities: runtime.capabilities,
                nativeWalletExecution: runtime.nativeWalletExecution,
                sendCallsSyncAsync: runtime.sendCallsSyncAsync
                  ? async (args) =>
                      runtime.sendCallsSyncAsync!({
                        ...args,
                        connector: runtime.activeConnector,
                      })
                  : undefined,
                sendTransactionAsync: async (args) =>
                  runtime.sendTransactionAsync!({
                    ...args,
                    connector: runtime.activeConnector,
                  }),
                switchChainAsync: runtime.switchChainAsync
                  ? async ({ chainId }) =>
                      runtime.switchChainAsync!({
                        chainId,
                        connector: runtime.activeConnector,
                      })
                  : undefined,
                chainsById: runtime.chainsById,
                getPreferredRpcUrl,
              },
              shouldUseExternalSigner: shouldUseExternalSignerForAA,
              resolveAAProviderState: runtime.resolveAAProviderState
                ? async (params) =>
                    runtime.resolveAAProviderState!(params, {
                      address: evm.selectEvmIdentity(Date.now()).address,
                      walletClient: shouldUseExternalSignerForAA
                        ? await runtime.getWalletClientFor({
                            connector: runtime.activeConnector,
                            chainId: params.callList[0]?.chainId,
                          })
                        : runtime.walletClient,
                    })
                : undefined,
              forceAA: runtime.aaPolicy !== "off",
              preferAAForSingleCall: runtime.aaPolicy !== "off",
              aaPolicy: runtime.aaPolicy,
              aaModes: runtime.aaModes,
              aaProvider: runtime.aaProvider,
            })
        : undefined),
    signTypedData:
      runtime.signTypedData ??
      (runtime.signTypedDataAsync
        ? async (payload) => {
            const signArgs = toViemSignTypedDataArgs(payload);
            if (!signArgs) {
              throw new Error("Missing typed_data payload");
            }
            const signature = await runtime.signTypedDataAsync!({
              ...(signArgs as Record<string, unknown>),
              connector: runtime.activeConnector,
            } as never);
            return { signature };
          }
        : undefined),
    signMessage:
      runtime.signMessage ??
      (runtime.signMessageAsync
        ? async (payload) => {
            const messageArgs = toViemSignMessageArgs(payload);
            if (!messageArgs) {
              throw new Error("Missing non_typed_data payload");
            }
            const signature = await runtime.signMessageAsync!({
              ...(messageArgs as Record<string, unknown>),
              connector: runtime.activeConnector,
            } as never);
            return { signature };
          }
        : undefined),
  };
}

"use client";

import type { Chain } from "viem";
import type {
  NativeWalletExecutionPolicy as ClientNativeWalletExecutionPolicy,
  SponsorshipPaymasterServiceContext,
  WalletTxPayload,
} from "@aomi-labs/react";
import {
  DISABLED_PROVIDER_STATE,
  aaModeFromExecutionKind,
  executeWalletCalls,
  toAAWalletCalls,
} from "@aomi-labs/react";
import type { AomiTxResult } from "../types";

export type RequestedAAMode = "none" | "4337" | "7702";
export type WalletKitAAPolicy = "off" | "optional" | "required";
export type WalletKitAAProviderPreference = "auto" | "alchemy" | "pimlico";
export type WalletProviderState = Parameters<
  typeof executeWalletCalls
>[0]["providerState"];
export type WalletExecutionCallList = Parameters<
  typeof executeWalletCalls
>[0]["callList"];

export type WalletExecutionKitState = {
  currentChainId?: number;
  capabilities?: Parameters<typeof executeWalletCalls>[0]["capabilities"];
  nativeWalletExecution?: NativeWalletExecutionPolicy;
  sendCallsSyncAsync?: Parameters<
    typeof executeWalletCalls
  >[0]["sendCallsSyncAsync"];
  sendTransactionAsync?: Parameters<
    typeof executeWalletCalls
  >[0]["sendTransactionAsync"];
  switchChainAsync?: Parameters<
    typeof executeWalletCalls
  >[0]["switchChainAsync"];
  chainsById: Record<number, Chain>;
  getPreferredRpcUrl?: (chain: Chain) => string;
};

export type NativeWalletExecutionPolicy = Omit<
  ClientNativeWalletExecutionPolicy,
  "sponsorship"
> & {
  sponsorship?:
    | { mode: "disabled" }
    | {
        mode: "optional";
        getPaymasterServiceContext?: (
          chainId: number,
        ) => SponsorshipPaymasterServiceContext | undefined;
        getPaymasterServiceUrl?: (chainId: number) => string | undefined;
      }
    | {
        mode: "required";
        getPaymasterServiceContext?: (
          chainId: number,
        ) => SponsorshipPaymasterServiceContext | undefined;
        getPaymasterServiceUrl?: (chainId: number) => string | undefined;
      };
};

export type ResolveAAProviderState = (params: {
  callList: WalletExecutionCallList;
  chainsById: Record<number, Chain>;
  requestedMode: Exclude<RequestedAAMode, "none">;
  shouldUseExternalSigner: boolean;
  sponsored?: boolean;
  provider?: WalletKitAAProviderPreference;
}) => Promise<{
  providerState: WalletProviderState;
  resolvedMode: RequestedAAMode;
  fallbackReason?: string;
}>;

export function getPreferredRpcUrl(chain: Chain): string {
  return chain.rpcUrls.default.http[0] ?? chain.rpcUrls.public?.http[0] ?? "";
}

export function resolveRequestedAAMode(
  payload: WalletTxPayload,
  isBatch: boolean,
  preferAAForSingleCall = false,
  forceAA = false,
): RequestedAAMode {
  if (!forceAA && !isBatch && !preferAAForSingleCall) return "none";
  if (!forceAA && payload.aaPreference === "none" && isBatch) return "none";
  if (payload.aaPreference === "eip4337") return "4337";
  return "7702";
}

export function normalizeAtomicCapabilities(
  raw: Parameters<typeof executeWalletCalls>[0]["capabilities"] | undefined,
): Parameters<typeof executeWalletCalls>[0]["capabilities"] | undefined {
  if (!raw) return undefined;

  const normalized: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(raw as Record<string, unknown>)) {
    if (!value || typeof value !== "object" || Array.isArray(value)) {
      normalized[key] = value;
      continue;
    }

    const record = value as {
      atomic?: { status?: string };
      [field: string]: unknown;
    };
    normalized[key] =
      record.atomic?.status === "ready"
        ? {
            ...record,
            atomic: {
              ...record.atomic,
              status: "supported",
            },
          }
        : value;
  }

  return normalized as Parameters<typeof executeWalletCalls>[0]["capabilities"];
}

function buildAaAttempts(
  aaRequestedMode: RequestedAAMode,
  shouldUseExternalSigner: boolean,
  allowedModes?: readonly Exclude<RequestedAAMode, "none">[],
): Array<{
  requestedMode: Exclude<RequestedAAMode, "none">;
  sponsored?: boolean;
}> {
  const allowed = allowedModes?.length ? new Set(allowedModes) : null;
  const filterAllowed = (
    attempts: Array<{
      requestedMode: Exclude<RequestedAAMode, "none">;
      sponsored?: boolean;
    }>,
  ) =>
    allowed
      ? attempts.filter((attempt) => allowed.has(attempt.requestedMode))
      : attempts;

  if (aaRequestedMode === "7702") {
    if (shouldUseExternalSigner) {
      return filterAllowed([{ requestedMode: "4337", sponsored: true }]);
    }
    return filterAllowed([
      { requestedMode: "7702" },
      { requestedMode: "4337", sponsored: true },
    ]);
  }

  if (aaRequestedMode === "4337") {
    return filterAllowed([{ requestedMode: "4337", sponsored: true }]);
  }

  return [];
}

function resolveNativeWalletExecutionPolicy({
  policy,
  chainId,
  requiresAtomicForBatch,
}: {
  policy?: NativeWalletExecutionPolicy;
  chainId: number;
  requiresAtomicForBatch: boolean;
}): ClientNativeWalletExecutionPolicy | undefined {
  if (!policy && !requiresAtomicForBatch) {
    return undefined;
  }

  const sponsorship =
    policy?.sponsorship?.mode === "optional" ||
    policy?.sponsorship?.mode === "required"
      ? {
          mode: policy.sponsorship.mode,
          paymasterServiceContext:
            policy.sponsorship.getPaymasterServiceContext?.(chainId),
          paymasterServiceUrl:
            policy.sponsorship.getPaymasterServiceUrl?.(chainId),
        }
      : policy?.sponsorship;

  return {
    executionKind: policy?.executionKind,
    requiresAtomicForBatch:
      requiresAtomicForBatch || policy?.requiresAtomicForBatch,
    sendCallsTimeoutMs: policy?.sendCallsTimeoutMs,
    sendCallsVersion: policy?.sendCallsVersion,
    sponsorship,
  };
}

function hasResolvedAAProviderState(
  providerState: WalletProviderState,
): boolean {
  return Boolean(providerState.resolved);
}

export async function executeWalletKitTransaction({
  payload,
  state,
  shouldUseExternalSigner = false,
  resolveAAProviderState,
  preferAAForSingleCall = false,
  forceAA = false,
  aaPolicy = "optional",
  aaModes,
  aaProvider = "auto",
}: {
  payload: WalletTxPayload;
  state: WalletExecutionKitState;
  shouldUseExternalSigner?: boolean;
  resolveAAProviderState?: ResolveAAProviderState;
  preferAAForSingleCall?: boolean;
  forceAA?: boolean;
  aaPolicy?: WalletKitAAPolicy;
  aaModes?: readonly Exclude<RequestedAAMode, "none">[];
  aaProvider?: WalletKitAAProviderPreference;
}): Promise<AomiTxResult> {
  if (!payload.to && (!payload.calls || payload.calls.length === 0)) {
    throw new Error("pending_transaction_missing_call_data");
  }

  if (!state.sendTransactionAsync) {
    throw new Error("wallet_send_transaction_not_supported");
  }
  const sendTransactionAsync = state.sendTransactionAsync;

  const callList = toAAWalletCalls(
    payload,
    payload.chainId ?? state.currentChainId ?? 1,
  );
  const isBatch = callList.length > 1;
  const aaRequestedMode = resolveRequestedAAMode(
    payload,
    isBatch,
    preferAAForSingleCall,
    forceAA,
  );
  const requiresSponsoredExecution =
    state.nativeWalletExecution?.sponsorship?.mode === "required";
  // Atomic-required is a payload-level intent (`aaStrict === true`),
  // independent of the provider's sponsorship mode. Conflating them
  // (commit 1d406d2) forces every sponsored batch into atomic+no-fallback
  // and breaks fee-injected 2-call batches when the wallet/bundler errors
  // after sign. `requiresSponsoredExecution` still drives fail-closed
  // semantics in the AA-failure exit path below.
  const requiresAtomicForBatch = isBatch && payload.aaStrict === true;
  const nativeWalletExecution = resolveNativeWalletExecutionPolicy({
    policy: state.nativeWalletExecution,
    chainId: callList[0]?.chainId ?? state.currentChainId ?? 1,
    requiresAtomicForBatch,
  });

  const executeWithProviderState = async (providerState: WalletProviderState) =>
    executeWalletCalls({
      callList,
      currentChainId: state.currentChainId ?? callList[0]?.chainId ?? 1,
      capabilities: state.capabilities,
      localPrivateKey: null,
      nativeWalletExecution,
      providerState,
      sendCallsSyncAsync: state.sendCallsSyncAsync
        ? async (args) => {
            return state.sendCallsSyncAsync?.({
              ...args,
            });
          }
        : async () => {
            throw new Error("wallet_send_calls_not_supported");
          },
      sendTransactionAsync,
      switchChainAsync: state.switchChainAsync
        ? async ({ chainId }) => {
            return state.switchChainAsync?.({ chainId });
          }
        : async () => {
            throw new Error("wallet_switch_chain_not_supported");
          },
      chainsById: state.chainsById,
      getPreferredRpcUrl: state.getPreferredRpcUrl ?? getPreferredRpcUrl,
    });

  let execution: Awaited<ReturnType<typeof executeWalletCalls>> | null = null;
  let finalFallbackReason: string | undefined;
  let lastAAError: unknown;
  let sawUnresolvedAAProviderState = false;
  const aaStateResolver = resolveAAProviderState;
  const aaAttempts =
    aaPolicy !== "off" && aaStateResolver
      ? buildAaAttempts(aaRequestedMode, shouldUseExternalSigner, aaModes)
      : [];

  if (aaAttempts.length === 0) {
    if (aaPolicy === "required" && aaRequestedMode !== "none") {
      throw new Error("aa_required_execution_failed");
    }
    execution = await executeWithProviderState(DISABLED_PROVIDER_STATE);
  } else {
    if (!aaStateResolver) {
      throw new Error("aa_provider_state_resolver_missing");
    }
    for (const attempt of aaAttempts) {
      const attemptState = await aaStateResolver({
        callList,
        chainsById: state.chainsById,
        requestedMode: attempt.requestedMode,
        shouldUseExternalSigner,
        sponsored: attempt.sponsored,
        provider: aaProvider,
      });

      if (attemptState.fallbackReason && !finalFallbackReason) {
        finalFallbackReason = attemptState.fallbackReason;
      }

      if (!hasResolvedAAProviderState(attemptState.providerState)) {
        sawUnresolvedAAProviderState = true;
        continue;
      }

      try {
        execution = await executeWithProviderState(attemptState.providerState);
        if (
          aaRequestedMode === "7702" &&
          attempt.requestedMode === "4337" &&
          !finalFallbackReason
        ) {
          finalFallbackReason = "requested_7702_fallback_4337";
        }
        break;
      } catch (error) {
        lastAAError = error;
        console.warn("[aomi-wallet-kit] AA attempt failed", {
          requestedMode: attempt.requestedMode,
          error: error instanceof Error ? error.message : String(error),
        });
      }
    }

    if (!execution) {
      if (aaPolicy === "required" || requiresSponsoredExecution) {
        throw new Error(finalFallbackReason ?? "aa_required_execution_failed");
      }
      if (payload.aaStrict && lastAAError && !sawUnresolvedAAProviderState) {
        throw new Error(finalFallbackReason ?? "aa_required_execution_failed");
      }
      console.warn(
        "[aomi-wallet-kit] All AA attempts failed; falling back to native wallet",
        {
          error:
            lastAAError instanceof Error
              ? lastAAError.message
              : String(lastAAError ?? "unknown"),
        },
      );
      execution = await executeWithProviderState(DISABLED_PROVIDER_STATE);
      finalFallbackReason = finalFallbackReason ?? "aa_failed_fallback_eoa";
    }
  }

  if (!execution.txHash) {
    throw new Error("wallet_execution_missing_transaction_hash");
  }

  const aaResolvedMode: RequestedAAMode =
    aaModeFromExecutionKind(execution.executionKind) ?? "none";

  return {
    txHash: execution.txHash,
    amount: payload.value,
    aaRequestedMode,
    aaResolvedMode,
    aaFallbackReason:
      finalFallbackReason ??
      (aaRequestedMode === "7702" && aaResolvedMode === "4337"
        ? "requested_7702_fallback_4337"
        : aaRequestedMode !== "none" && aaResolvedMode === "none"
          ? "aa_unavailable_fallback_eoa"
          : undefined),
    executionKind: execution.executionKind,
    batched: execution.batched,
    callCount: callList.length,
    sponsored: execution.sponsored,
    SmartAccount4337: execution.SmartAccount4337,
    Delegation7702: execution.Delegation7702,
  };
}

"use client";

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import type { Chain } from "viem";
import type { AomiNetworkTarget, SvmNetworkOption } from "./types";
import { resolveSelectedSvmNetwork } from "./runtime/svm/networks";
import { loadWalletPreferences, saveWalletPreferences } from "./persistence";

type NetworkPreferencesContextValue = {
  selectedEvmChainId?: number;
  selectedSolanaNetworkId?: string;
  supportedEvmChains: readonly Chain[];
  supportedSolanaNetworks: readonly SvmNetworkOption[];
  selectedSolanaNetwork?: SvmNetworkOption;
  setSelectedEvmChainId: (chainId: number | undefined) => void;
  setSelectedSolanaNetworkId: (networkId: string | undefined) => void;
  selectTarget: (target: AomiNetworkTarget) => void;
};

const NetworkPreferencesContext =
  createContext<NetworkPreferencesContextValue | null>(null);

export function AomiWalletNetworkPreferencesProvider({
  children,
  evmChains,
  solanaNetworks,
  storageKey = "default",
}: {
  children: ReactNode;
  evmChains: readonly Chain[];
  solanaNetworks: readonly SvmNetworkOption[];
  storageKey?: string;
}) {
  const [persisted] = useState(() => loadWalletPreferences(storageKey));

  const [selectedEvmChainId, setSelectedEvmChainId] = useState<
    number | undefined
  >(() =>
    persisted.selectedEvmChainId !== undefined &&
    evmChains.some((chain) => chain.id === persisted.selectedEvmChainId)
      ? persisted.selectedEvmChainId
      : evmChains[0]?.id,
  );
  const [selectedSolanaNetworkId, setSelectedSolanaNetworkId] = useState<
    string | undefined
  >(() =>
    persisted.selectedSolanaNetworkId &&
    solanaNetworks.some((n) => n.id === persisted.selectedSolanaNetworkId)
      ? persisted.selectedSolanaNetworkId
      : resolveSelectedSvmNetwork(solanaNetworks)?.id,
  );

  useEffect(() => {
    if (!evmChains.length) {
      setSelectedEvmChainId(undefined);
      return;
    }
    setSelectedEvmChainId((current) =>
      evmChains.some((chain) => chain.id === current)
        ? current
        : evmChains[0]?.id,
    );
  }, [evmChains]);

  useEffect(() => {
    if (!solanaNetworks.length) {
      setSelectedSolanaNetworkId(undefined);
      return;
    }
    setSelectedSolanaNetworkId((current) =>
      solanaNetworks.some((network) => network.id === current)
        ? current
        : resolveSelectedSvmNetwork(solanaNetworks)?.id,
    );
  }, [evmChains.length, solanaNetworks]);

  useEffect(() => {
    saveWalletPreferences(storageKey, {
      selectedEvmChainId,
      selectedSolanaNetworkId,
    });
  }, [storageKey, selectedEvmChainId, selectedSolanaNetworkId]);

  const selectedSolanaNetwork = useMemo(
    () =>
      solanaNetworks.length
        ? resolveSelectedSvmNetwork(solanaNetworks, selectedSolanaNetworkId)
        : undefined,
    [selectedSolanaNetworkId, solanaNetworks],
  );

  const value = useMemo<NetworkPreferencesContextValue>(
    () => ({
      selectedEvmChainId,
      selectedSolanaNetworkId,
      supportedEvmChains: evmChains,
      supportedSolanaNetworks: solanaNetworks,
      selectedSolanaNetwork,
      setSelectedEvmChainId,
      setSelectedSolanaNetworkId,
      selectTarget: (target: AomiNetworkTarget) => {
        if (target.family === "evm") {
          setSelectedEvmChainId(target.chainId);
          return;
        }
        setSelectedSolanaNetworkId(target.networkId);
      },
    }),
    [
      evmChains,
      selectedEvmChainId,
      selectedSolanaNetwork,
      selectedSolanaNetworkId,
      solanaNetworks,
    ],
  );

  return (
    <NetworkPreferencesContext.Provider value={value}>
      {children}
    </NetworkPreferencesContext.Provider>
  );
}

export function useAomiWalletNetworkPreferences(): NetworkPreferencesContextValue {
  const context = useContext(NetworkPreferencesContext);
  if (!context) {
    throw new Error(
      "useAomiWalletNetworkPreferences must be used within AomiWalletNetworkPreferencesProvider",
    );
  }
  return context;
}

/**
 * Non-throwing variant for components that may render without a wallet
 * provider in the tree — e.g. a standalone <AomiFrame /> on a docs page or
 * during SSR/prerender, where no wallet kit provider mounts the network
 * preferences context. Returns null when the provider is absent so callers
 * can degrade gracefully instead of crashing the render.
 */
export function useOptionalAomiWalletNetworkPreferences(): NetworkPreferencesContextValue | null {
  return useContext(NetworkPreferencesContext);
}

