/**
 * Identify which wallet brand actually answers behind an injected provider.
 *
 * Connector names lie: with Rabby (or Phantom, Brave, …) set as the default
 * wallet, the "MetaMask" connector binds to Rabby's provider — Rabby sets
 * `isMetaMask` for compatibility. So specific-brand flags are checked before
 * the generic `isMetaMask`.
 */
export function detectEvmProviderBrand(provider: unknown): string | undefined {
  if (!provider || typeof provider !== "object") return undefined;
  if (readInjectedFlag(provider, "isRabby")) return "Rabby";
  if (readInjectedFlag(provider, "isPhantom")) return "Phantom";
  if (readInjectedFlag(provider, "isBraveWallet")) return "Brave Wallet";
  if (readInjectedFlag(provider, "isRainbow")) return "Rainbow";
  if (readInjectedFlag(provider, "isCoinbaseWallet")) {
    return "Coinbase Wallet";
  }
  if (readInjectedFlag(provider, "isMetaMask")) return "MetaMask";
  return undefined;
}

export type EvmConnectionBrandInput = {
  connectorId: string;
  address: string;
};

/**
 * Resolve the real brand for each live EVM connection by sniffing the
 * underlying provider. Returns `connectorId → brand label`; connections whose
 * provider exposes no brand flags (embedded SDK wallets, WalletConnect, ...) are
 * absent — callers fall back to the connector name.
 *
 * Re-sniffs whenever the connection set changes, so flipping the wallet's
 * "default wallet" setting is picked up without a page refresh.
 */
export function useEvmProviderBrands(
  connections: readonly EvmConnectionBrandInput[],
  connectors: readonly Connector[],
): Record<string, string> {
  const [brands, setBrands] = useState<Record<string, string>>({});
  // Re-sniff on membership changes without retriggering on unrelated renders.
  const membershipKey = useMemo(
    () =>
      connections
        .map((connection) => `${connection.connectorId}:${connection.address}`)
        .sort()
        .join("|"),
    [connections],
  );
  const connectionsRef = useRef(connections);
  connectionsRef.current = connections;
  const connectorsRef = useRef(connectors);
  connectorsRef.current = connectors;

  useEffect(() => {
    if (!membershipKey) {
      setBrands((previous) => (Object.keys(previous).length ? {} : previous));
      return;
    }

    let cancelled = false;
    void Promise.all(
      connectionsRef.current.map(async (connection) => {
        const connector = connectorsRef.current.find(
          (candidate) => candidate.uid === connection.connectorId,
        );
        if (!connector?.getProvider) return null;
        try {
          const provider = await connector.getProvider();
          const brand = detectEvmProviderBrand(provider);
          return brand ? ([connection.connectorId, brand] as const) : null;
        } catch {
          return null;
        }
      }),
    ).then((entries) => {
      if (cancelled) return;
      setBrands(
        Object.fromEntries(
          entries.filter(
            (entry): entry is readonly [string, string] => entry !== null,
          ),
        ),
      );
    });

    return () => {
      cancelled = true;
    };
  }, [membershipKey]);

  return brands;
}

import type { WalletSource } from "../../types";

export type GracefulEvmIdentity = {
  address?: string;
  chainId?: number;
  connectorId?: string;
  walletName?: string;
  walletSource?: WalletSource;
};

export type GracefulEvmIdentityResult = {
  identity: GracefulEvmIdentity;
  disconnectedAt: number | null;
  usingCachedIdentity: boolean;
};

export function resolveGracefulEvmIdentity({
  current,
  previous,
  selectedChainId,
  disconnectedAt,
  now,
  graceMs,
  explicitDisconnect,
}: {
  current: GracefulEvmIdentity;
  previous: GracefulEvmIdentity | null;
  selectedChainId?: number;
  disconnectedAt: number | null;
  now: number;
  graceMs: number;
  explicitDisconnect: boolean;
}): GracefulEvmIdentityResult {
  if (current.address) {
    return {
      identity: current,
      disconnectedAt: null,
      usingCachedIdentity: false,
    };
  }

  if (!previous?.address || explicitDisconnect) {
    return {
      identity: current,
      disconnectedAt: null,
      usingCachedIdentity: false,
    };
  }

  const startedAt = disconnectedAt ?? now;
  if (now - startedAt > graceMs) {
    // Keep the original disconnect timestamp: resetting it to null here
    // would let the very next render restart the grace window (previous is
    // still cached), making the identity oscillate cached → empty → cached
    // for as long as the wallet stays disconnected. Only a live reconnect
    // (the `current.address` branch above) clears the timestamp.
    return {
      identity: current,
      disconnectedAt: startedAt,
      usingCachedIdentity: false,
    };
  }

  return {
    identity: {
      ...previous,
      chainId: selectedChainId ?? current.chainId ?? previous.chainId,
    },
    disconnectedAt: startedAt,
    usingCachedIdentity: true,
  };
}

"use client";

import type {
  SvmCluster,
  SvmNetworkConfigInput,
  SvmNetworkOption,
} from "../../types";

export const DEFAULT_SVM_CLUSTER: SvmCluster = "solana:mainnet";

export const DEFAULT_SVM_RPC_HTTP_URLS: Record<SvmCluster, string> = {
  "solana:mainnet": "https://api.mainnet-beta.solana.com",
  "solana:devnet": "https://api.devnet.solana.com",
  "solana:testnet": "https://api.testnet.solana.com",
};

export function getDefaultSvmNetworkLabel(cluster: SvmCluster): string {
  switch (cluster) {
    case "solana:mainnet":
      return "Solana Mainnet";
    case "solana:testnet":
      return "Solana Testnet";
    case "solana:devnet":
    default:
      return "Solana Devnet";
  }
}

function buildLegacySvmNetwork(
  config?: SvmNetworkConfigInput,
): SvmNetworkOption {
  const cluster = config?.cluster ?? DEFAULT_SVM_CLUSTER;
  return {
    id: cluster,
    label: getDefaultSvmNetworkLabel(cluster),
    cluster,
    rpcHttpUrl: config?.rpcHttpUrl ?? DEFAULT_SVM_RPC_HTTP_URLS[cluster],
    rpcWsUrl: config?.rpcWsUrl,
    isDefault: true,
  };
}

export function normalizeSvmNetworkOptions(
  config?: SvmNetworkConfigInput,
): readonly SvmNetworkOption[] {
  const rawNetworks = config?.networks;
  if (!rawNetworks || rawNetworks.length === 0) {
    return [buildLegacySvmNetwork(config)];
  }

  return rawNetworks.map((network, index) => ({
    id: network.id,
    label: network.label || getDefaultSvmNetworkLabel(network.cluster),
    cluster: network.cluster,
    rpcHttpUrl:
      network.rpcHttpUrl ?? DEFAULT_SVM_RPC_HTTP_URLS[network.cluster],
    rpcWsUrl: network.rpcWsUrl,
    isDefault:
      network.isDefault ??
      (index === 0 && !rawNetworks.some((item) => item.isDefault)),
  }));
}

export function resolveSelectedSvmNetwork(
  networks: readonly SvmNetworkOption[],
  selectedNetworkId?: string,
): SvmNetworkOption {
  return (
    networks.find((network) => network.id === selectedNetworkId) ??
    networks.find((network) => network.isDefault) ??
    networks[0]
  );
}

export function buildDefaultSvmNetworkOptions(options?: {
  mainnetRpcHttpUrl?: string;
  mainnetRpcWsUrl?: string;
  devnetRpcHttpUrl?: string;
  devnetRpcWsUrl?: string;
  testnetRpcHttpUrl?: string;
  testnetRpcWsUrl?: string;
}): readonly SvmNetworkOption[] {
  return [
    {
      id: "solana-mainnet",
      label: "Solana Mainnet",
      cluster: "solana:mainnet",
      rpcHttpUrl:
        options?.mainnetRpcHttpUrl ??
        DEFAULT_SVM_RPC_HTTP_URLS["solana:mainnet"],
      rpcWsUrl: options?.mainnetRpcWsUrl,
      isDefault: true,
    },
    {
      id: "solana-devnet",
      label: "Solana Devnet",
      cluster: "solana:devnet",
      rpcHttpUrl:
        options?.devnetRpcHttpUrl ?? DEFAULT_SVM_RPC_HTTP_URLS["solana:devnet"],
      rpcWsUrl: options?.devnetRpcWsUrl,
    },
    {
      id: "solana-testnet",
      label: "Solana Testnet",
      cluster: "solana:testnet",
      rpcHttpUrl:
        options?.testnetRpcHttpUrl ??
        DEFAULT_SVM_RPC_HTTP_URLS["solana:testnet"],
      rpcWsUrl: options?.testnetRpcWsUrl,
    },
  ];
}

"use client";

import {
  Connection as SolanaConnection,
  Transaction as SolanaTransaction,
  VersionedTransaction,
} from "@solana/web3.js";
import type {
  WalletSolanaSignMessagePayload,
  WalletSolanaSignPayload,
} from "@aomi-labs/react";
import type { SafeSvmWalletState } from "./wallet-runtime";

function decodeBase64(value: string): Uint8Array {
  if (typeof Buffer !== "undefined") {
    return new Uint8Array(Buffer.from(value, "base64"));
  }
  const bin = atob(value);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function encodeBase64(bytes: Uint8Array): string {
  if (typeof Buffer !== "undefined") {
    return Buffer.from(bytes).toString("base64");
  }
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
}

function deserializeSolanaTransaction(
  bytes: Uint8Array,
): VersionedTransaction | SolanaTransaction {
  try {
    return VersionedTransaction.deserialize(bytes);
  } catch {
    return SolanaTransaction.from(bytes);
  }
}

export function buildSvmTransactionMethods(
  wallet: SafeSvmWalletState,
  config: {
    rpcHttpUrl: string;
    rpcWsUrl?: string;
    preferDirectSend: boolean;
  },
): {
  signSolanaTransaction?: (
    payload: WalletSolanaSignPayload,
  ) => Promise<{ signedTx: string }>;
  signSolanaMessage?: (
    payload: WalletSolanaSignMessagePayload,
  ) => Promise<{ signature: string }>;
  sendSolanaTransaction?: (
    payload: WalletSolanaSignPayload,
  ) => Promise<{ signature: string; signedTx?: string }>;
  signAndSendSolanaTransaction?: (
    payload: WalletSolanaSignPayload,
  ) => Promise<{ signature: string; signedTx?: string }>;
  solanaRpcHttpUrl: string;
  solanaRpcWsUrl?: string;
} {
  const signTransaction = wallet.signTransaction;
  const signMessage = wallet.signMessage;
  const sendTransaction = wallet.sendTransaction;

  return {
    signSolanaTransaction: signTransaction
      ? async (payload: WalletSolanaSignPayload) => {
          if (!payload.unsignedTx) {
            throw new Error("Missing unsigned_tx payload");
          }
          const tx = deserializeSolanaTransaction(
            decodeBase64(payload.unsignedTx),
          );
          const signed = await signTransaction(tx);
          return { signedTx: encodeBase64(signed.serialize()) };
        }
      : undefined,
    signSolanaMessage: signMessage
      ? async (payload: WalletSolanaSignMessagePayload) => {
          if (!payload.message) {
            throw new Error("Missing message payload");
          }
          const signature = await signMessage(decodeBase64(payload.message));
          return { signature: encodeBase64(signature) };
        }
      : undefined,
    sendSolanaTransaction: sendTransaction
      ? async (payload: WalletSolanaSignPayload) => {
          if (!payload.unsignedTx) {
            throw new Error("Missing unsigned_tx payload");
          }
          const connection = new SolanaConnection(
            config.rpcHttpUrl,
            "confirmed",
          );
          const signature = await sendTransaction(
            deserializeSolanaTransaction(decodeBase64(payload.unsignedTx)),
            connection,
          );
          return { signature };
        }
      : undefined,
    signAndSendSolanaTransaction:
      sendTransaction && config.preferDirectSend
        ? async (payload: WalletSolanaSignPayload) => {
            if (!payload.unsignedTx) {
              throw new Error("Missing unsigned_tx payload");
            }
            const connection = new SolanaConnection(
              config.rpcHttpUrl,
              "confirmed",
            );
            const signature = await sendTransaction(
              deserializeSolanaTransaction(decodeBase64(payload.unsignedTx)),
              connection,
            );
            return { signature };
          }
        : undefined,
    solanaRpcHttpUrl: config.rpcHttpUrl,
    solanaRpcWsUrl: config.rpcWsUrl,
  };
}

"use client";

import { useCallback, useEffect, useMemo, useRef } from "react";
import { useWallet as useSolanaWallet } from "@solana/wallet-adapter-react";
import {
  Connection as SolanaConnection,
  Transaction as SolanaTransaction,
  VersionedTransaction,
} from "@solana/web3.js";
import type { AomiWalletOption, SvmNetworkOption, SvmWalletDescriptor } from "../../types";
import { SVM_WALLET_ALLOWLIST } from "../../catalog/svm-wallet-catalog";
import { canonicalWalletKey } from "../../catalog/wallet-branding";
import { selectAccounts, selectSvmIdentity } from "../../registry/selectors";
import type { WalletRegistryStore } from "../../registry/store";
import type { SvmWalletRuntime } from "../../composer/types";
import { DEFAULT_SVM_CLUSTER, DEFAULT_SVM_RPC_HTTP_URLS } from "./networks";
import { useSvmRegistrySource } from "./registry-source";
import { buildSvmTransactionMethods } from "./transactions";

export type SafeSvmWalletState = {
  publicKey: string | undefined;
  connected: boolean;
  connecting: boolean;
  disconnecting: boolean;
  walletName: string | undefined;
  wallets: Array<{
    adapter: {
      name: string;
      readyState: SolanaWalletReadyState;
    };
    readyState: SolanaWalletReadyState;
  }>;
  select: ((walletName: SolanaWalletName) => void) | undefined;
  connect: (() => Promise<void>) | undefined;
  disconnect: (() => Promise<void>) | undefined;
  signTransaction:
    | ((
        tx: VersionedTransaction | SolanaTransaction,
      ) => Promise<VersionedTransaction | SolanaTransaction>)
    | undefined;
  signAllTransactions:
    | ((
        txs: Array<VersionedTransaction | SolanaTransaction>,
      ) => Promise<Array<VersionedTransaction | SolanaTransaction>>)
    | undefined;
  signMessage: ((message: Uint8Array) => Promise<Uint8Array>) | undefined;
  sendTransaction:
    | ((
        tx: VersionedTransaction | SolanaTransaction,
        connection: SolanaConnection,
      ) => Promise<string>)
    | undefined;
};

export const DEFAULT_SVM_ENDPOINT =
  DEFAULT_SVM_RPC_HTTP_URLS[DEFAULT_SVM_CLUSTER];
export const SVM_AUTOCONNECT_GRACE_MS = 400;

type SolanaWalletReadyState =
  | "Installed"
  | "NotDetected"
  | "Loadable"
  | "Unsupported";
type SolanaWalletName = Parameters<
  ReturnType<typeof useSolanaWallet>["select"]
>[0];

export function useSafeSvmWallet(): SafeSvmWalletState {
  try {
    const wallet = useSolanaWallet();
    return {
      publicKey: wallet.publicKey?.toBase58(),
      connected: wallet.connected,
      connecting: wallet.connecting,
      disconnecting: wallet.disconnecting,
      walletName: wallet.wallet?.adapter?.name,
      wallets: wallet.wallets,
      select: wallet.select,
      connect: wallet.connect,
      disconnect: wallet.disconnect,
      signTransaction: wallet.signTransaction,
      signAllTransactions: wallet.signAllTransactions,
      signMessage: wallet.signMessage,
      sendTransaction: wallet.sendTransaction,
    };
  } catch {
    return {
      publicKey: undefined,
      connected: false,
      connecting: false,
      disconnecting: false,
      walletName: undefined,
      wallets: [],
      select: undefined,
      connect: undefined,
      disconnect: undefined,
      signTransaction: undefined,
      signAllTransactions: undefined,
      signMessage: undefined,
      sendTransaction: undefined,
    };
  }
}

export function detectSvmTransport(
  walletName: string | undefined,
): "extension" | "embedded" | "mwa" {
  const normalized = walletName?.toLowerCase() ?? "";
  if (
    normalized.includes("mobile wallet adapter") ||
    normalized.includes("solana mobile") ||
    normalized.includes("mwa")
  ) {
    return "mwa";
  }
  return "extension";
}

function isUsableWalletReadyState(readyState: SolanaWalletReadyState): boolean {
  return readyState === "Installed" || readyState === "Loadable";
}

function walletPriority(name: string): number {
  const normalized = name.toLowerCase();
  if (normalized.includes("phantom")) return 0;
  if (normalized.includes("solflare")) return 1;
  if (normalized.includes("backpack")) return 2;
  if (normalized.includes("glow")) return 3;
  return 10;
}

function pickPreferredSvmWallet(wallet: SafeSvmWalletState) {
  return [...wallet.wallets]
    .filter((candidate) => isUsableWalletReadyState(candidate.readyState))
    .sort((left, right) => {
      const installedDelta =
        Number(left.readyState === "Installed") -
        Number(right.readyState === "Installed");
      if (installedDelta !== 0) {
        return -installedDelta;
      }
      return (
        walletPriority(left.adapter.name) - walletPriority(right.adapter.name)
      );
    })[0];
}

export type SvmConnectAttempt =
  | { status: "connected" }
  | { status: "unavailable" }
  | {
      status: "selecting";
      walletName: string;
    };

export async function connectPreferredSvmWallet(
  wallet: SafeSvmWalletState,
): Promise<SvmConnectAttempt> {
  if (wallet.publicKey || wallet.connected) {
    return { status: "connected" };
  }

  if (!wallet.select || !wallet.connect) {
    return { status: "unavailable" };
  }

  if (wallet.walletName) {
    await wallet.connect();
    return { status: "connected" };
  }

  const selectedWallet = pickPreferredSvmWallet(wallet);
  if (!selectedWallet) {
    return { status: "unavailable" };
  }

  wallet.select(selectedWallet.adapter.name as SolanaWalletName);
  return { status: "selecting", walletName: selectedWallet.adapter.name };
}

export function getSvmCapabilitySnapshot(
  wallet: SafeSvmWalletState | undefined,
) {
  if (!wallet?.publicKey) {
    return undefined;
  }
  return {
    canSignMessage: Boolean(wallet.signMessage),
    canSignTransaction: Boolean(wallet.signTransaction),
    canSignAllTransactions: Boolean(wallet.signAllTransactions),
    canSendTransaction: Boolean(wallet.sendTransaction),
    canSignAndSendTransaction: Boolean(wallet.sendTransaction),
  };
}

export function buildSvmWalletDescriptors(
  wallet: SafeSvmWalletState,
): SvmWalletDescriptor[] {
  return wallet.wallets
    .filter((entry) =>
      SVM_WALLET_ALLOWLIST.has(canonicalWalletKey(entry.adapter.name)),
    )
    .map((entry) => ({
      name: entry.adapter.name,
      installed: entry.readyState === "Installed",
      ready:
        entry.readyState === "Installed" || entry.readyState === "Loadable",
    }));
}

export function toSvmWalletOption(
  descriptor: SvmWalletDescriptor,
): AomiWalletOption {
  return {
    id: descriptor.name,
    label: descriptor.name,
    family: "svm",
    kind: "solana",
    status: descriptor.ready
      ? descriptor.installed
        ? "installed"
        : "available"
      : "unavailable",
    installed: descriptor.installed,
    ready: descriptor.ready,
  };
}

function useLatestRef<T>(value: T) {
  const ref = useRef(value);
  useEffect(() => {
    ref.current = value;
  }, [value]);
  return ref;
}

export function useSvmWalletRuntime({
  registryStore,
  selectedNetwork,
  supportedNetworks,
  setSelectedNetworkId,
  wallet: walletOverride,
}: {
  registryStore: WalletRegistryStore;
  selectedNetwork?: SvmNetworkOption;
  supportedNetworks: readonly SvmNetworkOption[];
  setSelectedNetworkId: (id: string) => void;
  wallet?: SafeSvmWalletState;
}): SvmWalletRuntime {
  const safeWallet = useSafeSvmWallet();
  const wallet = walletOverride ?? safeWallet;
  const walletRef = useLatestRef(wallet);

  useSvmRegistrySource(registryStore, { svmWallet: wallet });

  const settleConnect = useCallback(
    (walletName: string) => {
      registryStore.dispatch({
        type: "svm/connect-settled",
        walletName,
        now: Date.now(),
      });
    },
    [registryStore],
  );

  const executeConnect = useCallback(
    async (walletName: string) => {
      const current = walletRef.current;
      try {
        if (current.publicKey && current.walletName === walletName) {
          return;
        }
        if (current.walletName !== walletName) {
          current.select?.(walletName as SolanaWalletName);
        }
        if (!current.connect) return;
        await new Promise((resolve) =>
          setTimeout(resolve, SVM_AUTOCONNECT_GRACE_MS),
        );
        await walletRef.current.connect?.();
      } finally {
        settleConnect(walletName);
      }
    },
    [settleConnect, walletRef],
  );

  const executeDisconnect = useCallback(async () => {
    const current = walletRef.current;
    if (!current.publicKey || !current.disconnect) return;
    await current.disconnect();
  }, [walletRef]);

  useEffect(() => {
    registryStore.updateExecutors({
      svmConnect: executeConnect,
      svmDisconnect: executeDisconnect,
    });
  }, [executeConnect, executeDisconnect, registryStore]);

  const connect = useCallback(
    async (optionId?: string) => {
      if (wallet.publicKey || wallet.connected) return;
      const walletName = optionId ?? pickPreferredSvmWallet(wallet)?.adapter.name;
      if (!walletName) return;
      registryStore.dispatch({
        type: "svm/connect-requested",
        walletName,
        now: Date.now(),
      });
    },
    [registryStore, wallet],
  );

  const disconnect = useCallback(async () => {
    registryStore.dispatch({
      type: "user/disconnect-family",
      family: "svm",
      now: Date.now(),
    });
  }, [registryStore]);

  const selectAccount = useCallback(
    async (accountId: string) => {
      const account = selectAccounts(registryStore.getSnapshot(), Date.now())
        .find((candidate) => candidate.family === "svm" && candidate.id === accountId);
      if (!account) return;
      registryStore.dispatch({
        type: "user/select-active",
        family: "svm",
        address: account.address,
        uid: account.id,
        stableId: account.id,
        now: Date.now(),
      });
    },
    [registryStore],
  );

  const selectNetwork = useCallback(
    async (networkId: string | number) => {
      const id = String(networkId);
      if (selectedNetwork?.id === id) return;
      if (wallet.publicKey && wallet.disconnect) {
        await wallet.disconnect();
      }
      setSelectedNetworkId(id);
    },
    [selectedNetwork?.id, setSelectedNetworkId, wallet],
  );

  const config = useMemo(
    () => ({
      rpcHttpUrl:
        selectedNetwork?.rpcHttpUrl ??
        DEFAULT_SVM_RPC_HTTP_URLS[selectedNetwork?.cluster ?? DEFAULT_SVM_CLUSTER],
      rpcWsUrl: selectedNetwork?.rpcWsUrl,
      preferDirectSend: true,
    }),
    [selectedNetwork],
  );
  const execution = useMemo(
    () => buildSvmTransactionMethods(wallet, config),
    [config, wallet],
  );
  const options = useMemo(
    () => buildSvmWalletDescriptors(wallet).map(toSvmWalletOption),
    [wallet],
  );
  const accounts = useCallback(
    (now: number) =>
      selectAccounts(registryStore.getSnapshot(), now).filter(
        (account) => account.family === "svm",
      ),
    [registryStore],
  );
  const identity = useCallback(
    (now: number) => {
      const registryIdentity = selectSvmIdentity(registryStore.getSnapshot(), now);
      return {
        ...registryIdentity,
        cluster: selectedNetwork?.cluster ?? DEFAULT_SVM_CLUSTER,
        walletSource: registryIdentity.address ? ("injected" as const) : undefined,
        transport: registryIdentity.address
          ? detectSvmTransport(registryIdentity.walletName)
          : undefined,
        capabilities: getSvmCapabilitySnapshot(wallet),
      };
    },
    [registryStore, selectedNetwork?.cluster, wallet],
  );

  return {
    status: wallet.select || wallet.connect || wallet.publicKey ? "ready" : "unavailable",
    registryStore,
    identity,
    accounts,
    activeAccount: accounts(Date.now()).find((account) => account.active),
    options,
    supportedNetworks,
    selectedNetwork,
    connect,
    disconnect,
    selectAccount,
    selectNetwork,
    execution,
  };
}

import type { WalletFamily, WalletSource } from "../types";

/** Runtime id vs stable id: wagmi connector `uid` is regenerated every page load;
 * `connector.id` (e.g. hosted SDK ids, "io.metamask", "metaMaskSDK", "walletConnect") is stable
 * across loads. Persist stable ids + addresses; resolve uids at runtime.
 */
export type RegistryConnection = {
  key: string;
  family: WalletFamily;
  uid: string;
  stableId: string;
  kind: "embedded-session" | "external-evm" | "walletconnect" | "svm";
  address: string;
  addresses: string[];
  chainId?: number;
  walletName?: string;
};

export type RegistryConnectionOrderItem = {
  family: WalletFamily;
  stableId: string;
  address: string;
};

export type ActiveRef = {
  family: WalletFamily;
  address: string;
  uid?: string;
  stableId?: string;
};

export type RegistryPhase = "booting" | "settling" | "stable" | "rebuilding";

export type EvmGraceState = {
  last: {
    address: string;
    chainId?: number;
    connectorId?: string;
    walletName?: string;
    walletSource?: WalletSource;
  } | null;
